import fs from 'node:fs';
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=read('sources/executori/web-0.txt');
const raw=[...new Map(read('sources/executori/raw.json').map(x=>[x.caseId+'/'+x.id,x])).values()];
const num=x=>x!==''&&x!=null&&Number.isFinite(Number(x))?Number(x):null;
const executor=raw.map(x=>{const a=x.asset,p=Object.fromEntries((a.properties||[]).map(p=>[p.propertyType,p.value]));return {
 id:'rep-'+x.caseId+'-'+x.id,source:'REPES / UNEJR',sourceUrl:`https://prod.executori.ro/repes/listing/${x.caseId}/${x.id}`,
 publicationUrl:`https://prod.executori.ro/repes/api/auctions/${x.caseId}/${x.id}/publication/`,
 title:a.name,category:({IMO:'Imobiliare',AMA:'Auto, moto și ambarcațiuni',MOB:'Bunuri mobile'})[a.type]||a.type,
 subcategory:tr[a.category+' - '+a.type]||a.category,price:a.price?.value??null,currency:a.price?.currency||null,
 county:a.address?.county||'',locality:a.address?.city||'',address:a.address?.originalAddress||'',description:a.description||'',
 image:a.pictures?.length?`https://prod.executori.ro/repes/api/auctions/${x.caseId}/${a.id}/pictures/${a.pictures[0]}/thumbnail`:null,
 publishedAt:x.publicationDate,auctionDate:x.date?.slice(0,10)||'',auctionTime:x.date?.slice(11,16)||'',seller:x.auctioneer?.organisation?.name||x.auctioneer?.person?.name||'',
 brand:p.MRK||'',year:num(p.YOP),fuel:tr[p.FUE]||p.FUE||'',area:num(p.USU||p.SUR),rooms:num(p.ROM),mileage:num(p.KMN),gearbox:tr[p.GEA]||p.GEA||'',
 attributes:{...Object.fromEntries((a.properties||[]).map(p=>[tr.auction.properties[p.propertyType]||p.propertyType,(tr[p.value]||p.value)+(p.unitOfMeasure?' '+(tr.common.unitOfMeasure[p.unitOfMeasure]||p.unitOfMeasure):'')])),
 'TVA declarat':a.vat==null?'Nespecificat':a.vat+'%','Garanție':a.guarantee?`${a.guarantee.value} ${a.guarantee.currency}`:'Nespecificată','Dosar':x.fileNo,'Stare în registru':x.status},detailFetched:true
 }});
fs.writeFileSync('sources/executori/listings.json',JSON.stringify(executor,null,2));
fs.writeFileSync('sources/executori/coverage.json',JSON.stringify({fetchedAt:new Date().toISOString(),uniqueListings:executor.length,rawRows:read('sources/executori/raw.json').length,source:'https://prod.executori.ro/repes/',unejr:'https://www.unejr.ro/',note:'UNEJR prezintă registrul public. Inventarul a fost preluat din REPES; nu sunt două inventare independente. Accesul direct UNEJR a eșuat; relația a fost verificată în pagina oficială indexată și termenii portalului.'},null,2));
const parseNum=x=>{if(x==null)return null;const s=String(x).trim().toLowerCase().replace(/\s*(mp|m²|km)$/,'').trim();if(/^\d{1,3}[.,]\d{3}$/.test(s))return null;return /^\d+(?:[.,]\d+)?$/.test(s)?Number(s.replace(',','.')):null};
const insolv=read('sources/insolventa/listings.json').filter(x=>x.sourceUrl).map(x=>({...x,auctionDate:/^\d{2}\/\d{2}\/\d{4}$/.test(x.auctionDate||'')?x.auctionDate.split('/').reverse().join('-'):x.auctionDate||'',area:parseNum(x.area),rooms:parseNum(x.attributes?.Camere),mileage:parseNum(x.attributes?.KM)}));
fs.mkdirSync('portal',{recursive:true});
const nav=(base='..')=>`<header><a class="logo" href="${base}/index.html"><span class="logo-mark">L</span> LICITAȚII <small>ROMÂNIA</small></a><nav aria-label="Navigare principală"><a href="${base}/catalog/index.html">ANABI</a><a href="${base}/executori/index.html">EXECUTORI</a><a href="${base}/insolventa/index.html">INSOLVENȚĂ</a></nav></header>`;
const head=(title,base='..')=>`<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} · Licitații România</title><link rel="stylesheet" href="${base}/portal/style.css"></head><body>${nav(base)}`;
const footer=`<footer>Catalog independent • Instantaneu din 12 octombrie 2026. Verifică publicația originală înainte de participare. Imaginile se încarcă de la sursă.</footer>`;
const select=(id,label,options='<option value="">Toate</option>')=>`<label>${label}<select id="${id}">${options}</select></label>`;
const input=(id,label,type='number')=>`<label>${label}<input id="${id}" type="${type}" ${type==='number'?'min="0"':''}></label>`;
for(const [slug,title,rows,source] of [['executori','Executori',executor,'REPES / UNEJR'],['insolventa','Insolvență',insolv,'licitatii-insolventa.ro']]){
 fs.mkdirSync(slug,{recursive:true});fs.writeFileSync(slug+'/data.js','window.LISTINGS='+JSON.stringify(rows).replace(/</g,'\\u003c')+';');
 const notice=slug==='executori'?`Date preluate din <a href="https://prod.executori.ro/repes/" target="_blank" rel="noopener">REPES ↗</a>. <a href="https://www.unejr.ro/" target="_blank" rel="noopener">UNEJR ↗</a> este portalul de acces la registru, prezentat aici într-un singur catalog. Conexiunea directă la UNEJR nu a răspuns; rolul portalului a fost verificat în <a href="https://www.unejr.ro/termeni-si-conditii/">pagina oficială indexată</a>.`:`Date preluate din <a href="https://www.licitatii-insolventa.ro/" target="_blank" rel="noopener">licitatii-insolventa.ro ↗</a>. Unele anunțuri au licitații repetate: data structurată poate fi anterioară următorului termen din descriere.`;
 fs.writeFileSync(slug+'/index.html',head(title)+`<main><div class="breadcrumb"><a href="../index.html">Acasă</a> / ${title}</div><section class="hero compact"><div><div class="eyebrow">CATALOG / ${source}</div><h1>${title}<span class="accent">.</span></h1><p>Găsește bunul potrivit. Filtrează anunțurile după categorie, locație și buget.</p></div><div class="total"><strong>${rows.length.toLocaleString('ro-RO')}</strong><span>anunțuri preluate</span></div></section><div class="source-note">${notice}</div><div id="categories" class="categories" aria-label="Categorii"></div><div class="searchbar"><label>Caută în anunțuri<input id="query" type="search" placeholder="Apartament, teren, BMW, utilaj…"></label><span>12 OCT 2026<br><small>Data colectării</small></span></div><div class="workspace"><aside><div class="filtertitle"><h2>Filtre</h2><button id="reset" class="text-button">Resetează</button></div>${select('category','Categorie')}${select('subcategory','Subcategorie')}${select('county','Județ')}${select('locality','Localitate')}${select('currency','Monedă','<option value="">Toate monedele</option><option>RON</option><option>EUR</option>')}<div class="pair">${input('priceMin','Preț minim')}${input('priceMax','Preț maxim')}</div><p class="hint">Pentru interval sau sortare după preț, selectează moneda. Prețurile rămân în moneda publicată, fără conversie.</p><div class="pair">${input('dateFrom','Licitație de la','date')}${input('dateTo','Până la','date')}</div><p class="hint">Filtrarea datei folosește termenul structurat din anunț; citește descrierea pentru reluări.</p><div id="autoFilters" hidden><h3>Auto și transport</h3>${select('brand','Marcă')}${select('fuel','Combustibil')}<div class="pair">${input('yearMin','An de la')}${input('yearMax','An până la')}</div>${input('mileageMax','Rulaj maxim (km)')}</div><div id="propertyFilters" hidden><h3>Imobiliare</h3><div class="pair">${input('areaMin','Suprafață min. m²')}${input('areaMax','Suprafață max. m²')}</div>${input('rooms','Număr camere')}</div><p class="hint">Caracteristicile lipsă nu sunt deduse. Un filtru specific exclude anunțurile fără acea informație. Categoriile și locațiile sunt cele declarate de sursă.</p></aside><section class="results-panel"><div class="result-head"><div><h2>Anunțuri selectate</h2><span id="count" aria-live="polite"></span></div>${select('sort','Ordonează','<option value="new">Cele mai noi</option><option value="date">Data licitației</option><option value="low">Preț crescător</option><option value="high">Preț descrescător</option>')}</div><div id="filterMessage" role="status"></div><div id="results" class="cards"></div><div class="pagination"><button id="prev">← Înapoi</button><span id="pageinfo"></span><button id="next">Înainte →</button></div></section></div></main>${footer}<dialog id="detail"><div id="detailContent"></div><form method="dialog"><button class="close">Închide</button></form></dialog><script src="data.js"></script><script src="../portal/app.js"></script></body></html>`);
}
fs.writeFileSync('index.html',head('Acasă','.')+`<main><section class="hero homehero"><div><div class="eyebrow">TREI SURSE. UN SINGUR LOC DE PORNIRE.</div><h1>Următoarea oportunitate<br>începe cu o <em>căutare.</em></h1><p>Explorează autoturisme, imobile și bunuri la licitație.<br>Alege sursa, apoi restrânge rezultatele la ceea ce te interesează.</p></div><div class="seal"><span>CATALOG</span><strong>12 / 10</strong><span>2026 · ROMÂNIA</span></div></section><div class="sectionline"><h2>Alege un catalog</h2><span>03 surse de explorat</span></div><section class="portals"><a class="portal-card" href="catalog/index.html"><span class="portal-number">01 / ANABI</span><div class="portal-icon">↗</div><h2>Autoturisme.<br>Prețuri în context.</h2><p>Fișe auto, VIN-uri disponibile și comparații documentate cu mobile.de.</p><div class="portal-bottom"><strong>393 <small>anunțuri cu arhivă</small></strong><span>Deschide →</span></div></a><a class="portal-card" href="executori/index.html"><span class="portal-number">02 / EXECUTORI</span><div class="portal-icon">⌂</div><h2>Bunuri din<br>executări silite.</h2><p>Registrul REPES / UNEJR: imobile, auto, ambarcațiuni și bunuri mobile.</p><div class="portal-bottom"><strong>${executor.length.toLocaleString('ro-RO')} <small>anunțuri</small></strong><span>Deschide →</span></div></a><a class="portal-card" href="insolventa/index.html"><span class="portal-number">03 / INSOLVENȚĂ</span><div class="portal-icon">◇</div><h2>Active pentru<br>un nou început.</h2><p>Afaceri, auto, imobiliare, echipamente industriale, office și alte bunuri.</p><div class="portal-bottom"><strong>${insolv.length.toLocaleString('ro-RO')} <small>anunțuri</small></strong><span>Deschide →</span></div></a></section><section class="home-note"><div><h3>De la categorie la detaliu</h3><p>Caută după cuvinte, județ, localitate, preț și data licitației. Filtrele auto și imobiliare apar când selectezi categoria.</p></div><div><h3>Sursele, la un click</h3><p><a href="https://anabi.just.ro/licitatiionline/ads?page=1&shortBy=price_high_to_low">ANABI ↗</a> · <a href="https://prod.executori.ro/repes/">REPES ↗</a> · <a href="https://www.unejr.ro/">UNEJR ↗</a> · <a href="https://www.licitatii-insolventa.ro/">Insolvență ↗</a></p><p>Catalog local, cu date la momentul colectării. Monitorizarea zilnică de la 08:00 urmărește anunțurile auto ANABI.</p></div></section></main>${footer}</body></html>`);
const cp='catalog/index.html';let c=fs.readFileSync(cp,'utf8');if(!c.includes('Înapoi la portal')){c=c.replace('<main>','<main><p><a href="../index.html">← Înapoi la portalul de licitații</a></p>');fs.writeFileSync(cp,c)}
fs.writeFileSync('CITESTE-MA.txt','Deschide index.html pentru portalul principal.\nANABI: catalog/index.html\nEXECUTORI: executori/index.html\nINSOLVENTA: insolventa/index.html\nFiltrele funcționează local. Imaginile și linkurile sursă necesită internet.\nDate colectate la 12.10.2026. Catalogul nu se actualizează în browser. Reminderul 08:00 urmărește doar anunțurile auto ANABI.\n');
console.log(JSON.stringify({executori:executor.length,insolventa:insolv.length}));
